# owner: platform
import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span

class RoundSpansTests(unittest.TestCase):
    def test_label_format(self):
        spans = [Span(540, 1035)]
        self.assertEqual(
            round_spans(spans, 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_snaps_to_nearest_step(self):
        spans = [Span(543, 1028)]
        self.assertEqual(
            round_spans(spans, 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_half_step_rounds_up(self):
        spans = [Span(540, 1035)]
        self.assertEqual(
            round_spans(spans, 30),
            ["09:00-17:30 (8h 30m)"]
        )

    def test_several_spans_keep_order(self):
        spans = [Span(60, 120), Span(600, 660)]
        self.assertEqual(
            round_spans(spans, 30),
            ["01:00-02:00 (1h 0m)", "10:00-11:00 (1h 0m)"]
        )

    def test_empty_list(self):
        self.assertEqual(round_spans([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 120):
            with self.assertRaises(ValueError):
                round_spans([Span(0, 60)], step)

    def test_span_collapsing_to_nothing_raises(self):
        with self.assertRaises(ValueError):
            round_spans([Span(61, 64)], 15)

if __name__ == "__main__":
    unittest.main()
